/* Scripted explanatory scene; no physics, model inference or measured outcomes. */
const HUMANOID_DEMO_STEPS=['Nhiệm vụ','Thực hiện','Lượt lỗi','Kiểm hệ thống','Can thiệp','Đo lại'];
function humanoidDemoMarkup(){return `<div class="humanoid-demo"><div class="humanoid-demo-view" aria-label="Cảnh humanoid 3D minh họa"></div><span class="humanoid-demo-tag">3D · CHUYỂN ĐỘNG THEO KỊCH BẢN</span><button type="button" class="humanoid-camera">Đổi góc nhìn</button><div class="humanoid-demo-caption" role="status">Đang chuẩn bị cảnh minh họa…</div></div>`;}
function humanoidDemoControls(){return `<div class="humanoid-controls"><button type="button" class="humanoid-play" aria-pressed="false">▶ Xem demo 30 giây</button><span>Chuyển động dựng để giải thích ý tưởng</span></div><div class="humanoid-steps" role="group" aria-label="Chọn bước trong demo">${HUMANOID_DEMO_STEPS.map((s,i)=>`<button type="button" data-humanoid-step="${i}" aria-pressed="false"><span>0${i+1}</span>${s}</button>`).join('')}</div>`;}
function initHumanoidDemo(figure,condition,health,signal,onStep){let alive=true,disposeScene=()=>{},pauseScene=()=>{};const wrapper=figure.querySelector('.humanoid-demo'),host=wrapper.querySelector('.humanoid-demo-view'),status=wrapper.querySelector('.humanoid-demo-caption'),play=figure.querySelector('.humanoid-play');
 play.disabled=true;
 function cleanup(){if(!alive)return;alive=false;disposeScene();}
 signal.addEventListener('abort',cleanup,{once:true});
 import('./vendor/three.module.min.js').then(T=>{if(!alive||signal.aborted)return;let renderer;try{renderer=new T.WebGLRenderer({antialias:true,alpha:false});}catch(error){wrapper.hidden=true;figure.querySelector('.humanoid-controls').hidden=true;figure.querySelector('.humanoid-steps').hidden=true;return;}
  figure.classList.add('has-3d');figure.querySelector('.opening-failure-image>img').setAttribute('aria-hidden','true');renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;host.appendChild(renderer.domElement);
  const scene=new T.Scene();scene.background=new T.Color('#edf2f7');const camera=new T.PerspectiveCamera(38,1,.1,30);let overhead=false;
  const materials={white:new T.MeshStandardMaterial({color:'#e4eaf1',metalness:.28,roughness:.38}),dark:new T.MeshStandardMaterial({color:'#28394d',metalness:.3,roughness:.45}),joint:new T.MeshStandardMaterial({color:'#6c87a6',metalness:.6,roughness:.35}),table:new T.MeshStandardMaterial({color:'#cbd5e0',metalness:.35,roughness:.45}),yellow:new T.MeshStandardMaterial({color:'#edbe39',roughness:.4}),tray:new T.MeshStandardMaterial({color:'#64778e',metalness:.2,roughness:.55}),green:new T.MeshStandardMaterial({color:'#4c9670',roughness:.6}),black:new T.MeshStandardMaterial({color:'#172b3c',metalness:.3,roughness:.25}),blue:new T.MeshStandardMaterial({color:'#53b2d5',emissive:'#20728c',emissiveIntensity:.4})};
  function mesh(geometry,material,x=0,y=0,z=0){const m=new T.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m;}
  function box(w,h,d,mat,x,y,z){return mesh(new T.BoxGeometry(w,h,d),mat,x,y,z);}
  function ball(r,mat,x,y,z){return mesh(new T.SphereGeometry(r,20,12),mat,x,y,z);}
  function link(a,b,r,mat){const m=mesh(new T.CylinderGeometry(r,r,1,20),mat);poseLink(m,a,b);return m;}
  const up=new T.Vector3(0,1,0);
  function poseLink(m,a,b){const dir=new T.Vector3().subVectors(b,a);m.position.copy(a).add(b).multiplyScalar(.5);m.scale.y=dir.length();m.quaternion.setFromUnitVectors(up,dir.normalize());}
  scene.add(new T.HemisphereLight('#ffffff','#a2adbd',2.3));const light=new T.DirectionalLight('#ffffff',3.2);light.position.set(-2.6,4.5,2.1);light.castShadow=true;light.shadow.mapSize.set(512,512);light.shadow.camera.left=-2;light.shadow.camera.right=2;light.shadow.camera.top=3;light.shadow.camera.bottom=-2;light.shadow.bias=-.0004;scene.add(light);
  const floor=mesh(new T.PlaneGeometry(20,20),new T.MeshStandardMaterial({color:'#e7edf4',roughness:.85}),0,0,0);floor.rotation.x=-Math.PI/2;floor.castShadow=false;
  box(2.05,.065,1.16,materials.table,0,.985,.25);for(const x of [-.85,.85])for(const z of [-.2,.7])box(.065,.95,.065,materials.dark,x,.49,z);box(2.05,.025,.035,materials.joint,0,.945,.83);
  box(.43,.46,.25,materials.white,0,1.38,-.4);box(.32,.22,.22,materials.dark,0,1.07,-.4);box(.36,.2,.22,materials.white,0,.86,-.4);mesh(new T.CylinderGeometry(.065,.065,.12,20),materials.joint,0,1.65,-.4);box(.29,.26,.25,materials.white,0,1.81,-.38);box(.25,.075,.018,materials.black,0,1.825,-.245);for(const x of [-.065,.065])ball(.012,materials.blue,x,1.83,-.229);box(.075,.26,.27,materials.joint,-.16,1.81,-.38);box(.075,.26,.27,materials.joint,.16,1.81,-.38);
  for(const x of [-.13,.13]){link(new T.Vector3(x,.82,-.4),new T.Vector3(x,.47,-.38),.068,materials.white);ball(.075,materials.joint,x,.45,-.38);link(new T.Vector3(x,.42,-.38),new T.Vector3(x,.12,-.37),.06,materials.white);box(.15,.08,.27,materials.dark,x,.07,-.31);}
  const shoulder=new T.Vector3(-.33,1.5,-.27);ball(.085,materials.joint,shoulder.x,shoulder.y,shoulder.z);ball(.085,materials.joint,.33,1.5,-.27);link(new T.Vector3(.33,1.5,-.27),new T.Vector3(.43,1.23,-.35),.06,materials.white);ball(.063,materials.joint,.43,1.23,-.35);link(new T.Vector3(.43,1.23,-.35),new T.Vector3(.47,.96,-.24),.05,materials.white);box(.09,.13,.075,materials.dark,.47,.92,-.24);
  const upper=link(shoulder,new T.Vector3(-.6,1.2,0),.062,materials.white),lower=link(new T.Vector3(-.6,1.2,0),new T.Vector3(-.45,1.19,.16),.052,materials.white),elbow=ball(.069,materials.joint,0,0,0),wristBall=ball(.045,materials.joint,0,0,0);
  const hand=new T.Group();scene.add(hand);function handBox(w,h,d,x,y,z,mat){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;hand.add(m);return m;}handBox(.11,.07,.085,0,-.035,0,materials.dark);const fingerA=handBox(.025,.13,.07,-.075,-.12,0,materials.white),fingerB=handBox(.025,.13,.07,.075,-.12,0,materials.white);
  const part=box(.12,.06,.09,materials.yellow,-.45,1.048,.16);box(.46,.025,.36,materials.tray,.45,1.032,.24);for(const x of [.22,.374,.527,.68])box(.012,.045,.36,materials.tray,x,1.055,.24);for(const z of [.06,.24,.42])box(.46,.045,.012,materials.tray,.45,1.055,z);box(.137,.004,.155,materials.green,.30,1.047,.329);
  const labelCanvas=document.createElement('canvas');labelCanvas.width=128;labelCanvas.height=64;const ctx=labelCanvas.getContext('2d');ctx.fillStyle='#e8f4ed';ctx.fillRect(0,0,128,64);ctx.fillStyle='#306444';ctx.font='bold 38px Arial';ctx.textAlign='center';ctx.fillText('A1',64,46);const texture=new T.CanvasTexture(labelCanvas);const tag=mesh(new T.PlaneGeometry(.12,.06),new T.MeshBasicMaterial({map:texture}),.30,1.052,.333);tag.rotation.x=-Math.PI/2;
  let step=2,q=1,playing=false,paused=false,start=0,elapsed=0,disposed=false,lastAnnounced=-1;
  const rest=new T.Vector3(-.35,1.35,.02),source=new T.Vector3(-.45,1.19,.16),miss=new T.Vector3(-.61,1.19,.16),target=new T.Vector3(.30,1.205,.329),lerp=(a,b,p)=>a.clone().lerp(b,p),smooth=p=>p*p*(3-2*p);
  function applyPose(s,p){let w=rest.clone(),gap=.074,px=-.45,py=1.048,pz=.16,rotation=0;const from=condition==='visual'?miss:source;
   if(s===1){w=lerp(rest,from,smooth(Math.min(1,p/.7)));gap=p>.7?.054:.074;}
   if(s>=2&&s<=4){const t=s===2?smooth(p):1;w=lerp(from,target,t);w.y+=Math.sin(t*Math.PI)*.16;gap=.054;if(condition==='contact'){if(t<.48){px=w.x;py=w.y-.14;pz=w.z;}else{const dropped=lerp(source,target,.48);px=dropped.x;py=1.048+Math.max(0,1-(t-.48)/.2)*.10;pz=dropped.z;rotation=Math.max(0,1-(t-.48)/.4)*.32;}}}
   if(s===5){const t=smooth(Math.min(1,p/.78));w=lerp(source,target,t);w.y+=Math.sin(t*Math.PI)*.16;gap=p>.82?.074:.054;if(p<=.82){px=w.x;py=w.y-.14;pz=w.z;}else{px=target.x;py=1.078;pz=target.z;w.y+=Math.min(1,(p-.82)/.18)*.17;}}
   const dir=w.clone().sub(shoulder),distance=dir.length(),L1=.51,L2=.54,a=(L1*L1-L2*L2+distance*distance)/(2*distance);dir.normalize();const perp=new T.Vector3(-1,-.1,.05);perp.addScaledVector(dir,-perp.dot(dir)).normalize();const e=shoulder.clone().addScaledVector(dir,a).addScaledVector(perp,Math.sqrt(Math.max(0,L1*L1-a*a)));poseLink(upper,shoulder,e);poseLink(lower,e,w);elbow.position.copy(e);wristBall.position.copy(w);hand.position.copy(w);fingerA.position.x=-gap;fingerB.position.x=gap;part.position.set(px,py,pz);part.rotation.z=rotation;light.intensity=condition==='visual'&&s>=1&&s<=4?2.3:3.2;
  }
  function describe(s){const labels=['Nhiệm vụ: đặt linh kiện vàng vào ô A1','Robot thực hiện theo mô hình — chuyển động minh họa',condition==='visual'?'Gắp hụt: vật vẫn ở trên bàn':'Trượt vật: linh kiện không tới ô đích','Lưu lượt lỗi, kỹ sư kiểm camera và điều khiển',health==='repair'?'Sửa hệ thống, lập lại baseline':condition==='visual'?'Thử gói biến thể ánh sáng phù hợp':'Thu mẫu robot về giữ và chuyển vật','Lượt mới minh họa · Đặt đúng là kết quả kỳ vọng'];status.textContent=labels[s];figure.querySelectorAll('[data-humanoid-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.humanoidStep)===s)));onStep(s);lastAnnounced=s;}
  function draw(){if(disposed)return;applyPose(step,q);renderer.render(scene,camera);}
  function resize(){const r=host.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();camera.position.set(overhead?-.1:-1.6,overhead?3.25:2.0,overhead?1.1:2.5);camera.lookAt(0,1.12,.08);draw();}
  function stop(resume=false){if(playing&&resume)elapsed=performance.now()-start;playing=false;paused=resume;renderer.setAnimationLoop(null);play.textContent=resume?'▶ Tiếp tục demo':'▶ Xem demo 30 giây';play.setAttribute('aria-pressed','false');}
  let lastPaint=0;
  function tick(now){if(now-lastPaint<1000/24)return;lastPaint=now;elapsed=now-start;step=Math.min(5,Math.floor(elapsed/5000));q=Math.min(1,(elapsed%5000)/5000);if(elapsed>=30000){step=5;q=1;stop();}if(step!==lastAnnounced)describe(step);draw();}
  const listener=e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('humanoid-camera')){overhead=!overhead;resize();}if(b.dataset.humanoidStep!==undefined){stop();step=Number(b.dataset.humanoidStep);q=1;elapsed=step*5000;describe(step);draw();}if(b===play){if(playing){stop(true);return;}playing=true;if(!paused){elapsed=0;}start=performance.now()-elapsed;play.textContent='Ⅱ Tạm dừng demo';play.setAttribute('aria-pressed','true');renderer.setAnimationLoop(tick);}};
  figure.addEventListener('click',listener);const observer=new ResizeObserver(resize);observer.observe(host);const visibility=()=>{if(document.hidden&&playing)stop(true);};document.addEventListener('visibilitychange',visibility);pauseScene=()=>{if(playing)stop(true);};
  disposeScene=()=>{disposed=true;stop();observer.disconnect();figure.removeEventListener('click',listener);document.removeEventListener('visibilitychange',visibility);scene.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const list=Array.isArray(o.material)?o.material:[o.material];list.forEach(m=>m.dispose());}});texture.dispose();renderer.forceContextLoss();renderer.dispose();};describe(2);resize();play.disabled=false;
 }).catch(()=>{if(alive){wrapper.hidden=true;figure.querySelector('.humanoid-controls').hidden=true;figure.querySelector('.humanoid-steps').hidden=true;}});
 return {dispose:cleanup,pause:()=>pauseScene()};
}
